class User {
  + name
  + surname
}

class Subscriber extends User {
  + cardBalance
}

class MovieShop {
  + browseCatalogue()
  + order()
  + subscribe()
}

class Movie {
  + title
}

class Order {
  + date
}

class MovieRent {
  + loanDate
  + price
}

User "1" -- "*" Order : places
User "1" -- "*" MovieRent : hires
MovieShop "1" -- "*" Movie : catalogues
MovieShop "1" -- "*" Order : manages
Movie "1" -- "*" Order : is part of
Movie "1" -- "*" MovieRent : is rented in

@enduml

